// ---------- III-11 Hear it right ----------
const HEAR = { play: [[['recognize speech', 0.4, 0.02], ['wreck a nice beach', 0.45, 0.0002], ['wreck an ice peach', 0.15, 0.00001]]], twist: [[['recognize speech', 0.4, 0.02], ['wreck a nice beach', 0.45, 0.0002], ['wreck an ice peach', 0.15, 0.00001]], [['Corvane’s Almanac', 0.55, 0.00002], ['Corvette almanac', 0.3, 0.004], ['curtain call', 0.15, 0.01]]] };
const heard = (c, lam) => { let b = 0, bv = -1e9; c.forEach((x, i) => { const v = Math.log(x[1]) + lam * Math.log(x[2]); if (v > bv) { bv = v; b = i; } }); return b; };
export const III11 = {
  id: 'III-11', name: 'Hear it right', short: 'Sound and sense', formula: 'choose the words W that make P(sound | W) × P(W) largest\nthe first part: what it sounded like\nthe second: how likely anyone is to say that',
  limit: 'Leaning on what is likely makes the recognizer right more often overall, and wrong in the same direction every time: toward the familiar.',
  rounds: { play: { brief: 'Someone has spoken. Three readings fit the sound, and the wrong one fits best. Drag the dial to give weight to how likely each phrase is, until it hears what was said.' }, twist: { brief: 'Two speakers now. The second asks for a rare title. Find a setting that hears both correctly.' }, case: { brief: 'A child asks the Common Shelf kiosk for one particular picture book. The kiosk’s idea of “likely” comes from loan counts. Turn the dial until it hears what was asked.' } },
  hints: { play: ['“Sounds like” alone is not enough.', 'A little weight on “likely” does it.'], twist: ['Too little and the first goes wrong. Too much and the second does.', 'Try about 0.07.'], case: ['Nobody has borrowed that book in years, so the kiosk thinks nobody would ask.', 'Turn the dial almost all the way down.'] },
  teach: ['List the phrases the sound could have been.', 'Weigh how well each fits the sound against how likely it is to be said.', 'Rare names lose that contest unless you turn the weight down.'],
  init(round, ctx) { if (round === 'case') { const C = ctx.caseData, top = C.titles.top[0], tot = C.y.loans[5] * 12; return { round, lam: 1, sets: [[[C.pip.name, 0.7, 1 / tot], [top.name, 0.2, top.last / tot], [C.titles.top[1].name, 0.1, C.titles.top[1].last / tot]]], want: [0] }; } return { round, lam: round === 'twist' ? 1 : 0, sets: HEAR[round], want: round === 'twist' ? [0, 0] : [0] }; },
  draw(b, s) {
    b.clear(); b.fit(); const A = area(b), u = A.u, rows = s.sets.length; s.sets.forEach((c, k) => { const y0 = A.y + 20 * u + k * ((A.h - 110 * u) / rows), h = heard(c, s.lam); b.label(rows > 1 ? 'Speaker ' + (k + 1) : 'What the microphone could have heard', A.x + 6 * u, y0, { bold: true }); c.forEach((x, i) => { const y = y0 + 18 * u + i * 46 * u; card(b, null, A.x + 6 * u, y, A.w * 0.42, 40 * u, x[0] + (i === s.want[k] ? '   (what was said)' : ''), { size: 12, align: 'left', fill: i === h ? (i === s.want[k] ? '#cfeadb' : '#fbe0d6') : '#fffdf5', sel: i === h }); b.box(A.x + A.w * 0.46, y + 6 * u, A.w * 0.22 * x[1], 12 * u, { fill: DATA[0] }); b.label('sounds like ' + pct(x[1]), A.x + A.w * 0.7, y + 12 * u, { size: 10 }); b.box(A.x + A.w * 0.46, y + 22 * u, A.w * 0.22 * clamp((Math.log10(x[2]) + 7) / 6, 0.02, 1), 12 * u, { fill: DATA[1] }); b.label('likely: 1 in ' + nice(Math.round(1 / x[2])), A.x + A.w * 0.7, y + 28 * u, { size: 10 }); }); });
    b.view(0, 1.2, 0, 1); b.pad = { l: 60, r: 60, t: b.h / b.u - 70, b: 34 }; b.line(0, 0.5, 1.2, 0.5, { color: INK2, width: 3 }); [0, 0.3, 0.6, 0.9, 1.2].forEach((v) => b.text(v.toFixed(1), v, 0.5, { dy: 14 * u, size: 10, mono: true })); b.handle('lam', s.lam, 0.5, { color: WARM, label: 'weight on “likely”: ' + s.lam.toFixed(2) }); b.pad = { l: 46, r: 18, t: 18, b: 38 };
  },
  drag(s, id, x) { if (id === 'lam') s.lam = clamp(Math.round(x * 100) / 100, 0, 1.2); },
  meter(s) { const ok = s.sets.filter((c, k) => heard(c, s.lam) === s.want[k]).length; return { label: 'Heard correctly', text: `${ok} of ${s.sets.length}`, frac: ok / s.sets.length, met: ok === s.sets.length, note: s.round === 'case' ? `it hears: “${s.sets[0][heard(s.sets[0], s.lam)][0]}”` : '' }; },
  demo(s) { for (let l = 0; l <= 1.2; l += 0.01) { s.lam = Math.round(l * 100) / 100; if (s.sets.every((c, k) => heard(c, s.lam) === s.want[k])) return; } },
};

// ---------- III-12 Forger and detective ----------
const dens = (x, modes) => sum(modes.map(([m, w]) => w * Math.exp(-((x - m) ** 2) / (2 * 0.045 ** 2))));
const nearMode = (x, modes) => { let b = -1, bd = 0.09; modes.forEach(([m], i) => { if (Math.abs(x - m) < bd) { bd = Math.abs(x - m); b = i; } }); return b; };
export const III12 = {
  id: 'III-12', name: 'Forger and detective', short: 'Adversarial networks', formula: 'the forger makes fakes; the detective scores each one: real or not?\neach learns from the other\na forger judged one stamp at a time can pass by making the same safe stamp for ever',
  limit: 'Passing inspection is not the same as covering what is real. A detective who looks at one item at a time cannot see that they are all alike.',
  rounds: { play: { brief: 'The hills show how dark real library stamps are: three designs. The detective passes a stamp that sits where real ones do. Drag your twelve forgeries until at least eleven pass.' }, twist: { brief: 'Every forgery passes, and they are all the same design. Spread them so each of the three designs gets at least three, with eleven still passing.' }, case: { brief: 'Hills: what Common Shelf readers borrow, by subject. Dots: ten suggestions, all on the safest subject. Cover all four subjects and keep nine “borrowed”.' } },
  hints: { play: ['Put each forgery under a hill.', 'Folio can place them.'], twist: ['Drag some to the left hill and some to the right.', 'Four under each hill.'], case: ['The small hill is the rare subject. Aim for its very top.', 'Three, three, three and one.'] },
  teach: ['One network makes fakes and another judges them.', 'The maker improves by fooling the judge.', 'Check the variety of what is made, not only whether each piece passes.'],
  two: { set: 'Draw a forged stamp.', solve: 'Pick it out from three real ones.' },
  init(round, ctx) { const r = ctx.rng(round); if (round === 'case') { const sh = ctx.caseData.subjectShare, w = [sh[0], sh[1], sh[2], sh[12]].map((v) => v / sh[0]); return { round, modes: [[0.15, w[0]], [0.4, w[1]], [0.65, w[2]], [0.88, Math.max(0.12, w[3])]], f: R(10, (i) => 0.13 + i * 0.004), need: 9, tau: 0.1, cover: 1, names: ['most-borrowed subject', 'second', 'third', 'a rare subject'] }; } const modes = [[0.2, 1], [0.5, 1], [0.8, 1]]; return { round, modes, f: round === 'twist' ? R(12, (i) => 0.48 + i * 0.004) : R(12, (i) => 0.04 + i * 0.083), need: 11, tau: 0.35, cover: round === 'twist' ? 3 : 0 }; },
  draw(b, s) { b.clear(); b.view(0, 1, -0.5, 1.3); b.axes({ x: s.round === 'case' ? 'subject' : 'how dark the stamp is', yt: 0, yfmt: () => '', xt: s.round === 'case' ? 0 : 5, xfmt: s.round === 'case' ? () => '' : undefined }); b.fn((x) => dens(x, s.modes), { color: DATA[0], width: 2.5, n: 300 }); b.line(0, s.tau, 1, s.tau, { color: INK2, dash: [5, 4] }); b.text(s.round === 'case' ? 'borrowed above this line' : 'passes above this line', 0.9, s.tau, { dy: -9 * b.u, size: 10 }); if (s.names) s.modes.forEach(([m], i) => b.text(s.names[i], m, -0.42, { size: 10.5 })); s.f.forEach((x, i) => { const ok = dens(x, s.modes) >= s.tau; b.line(x, -0.2, x, dens(x, s.modes), { color: ok ? GOOD : WARM, dash: [2, 3] }); b.handle('f' + i, x, -0.2 - (i % 3) * 0.06, { color: ok ? DATA[2] : DATA[3], r: 7 }); }); },
  drag(s, id, x) { if (id?.[0] === 'f') s.f[+id.slice(1)] = clamp(x, 0.01, 0.99); },
  meter(s) { const pass = s.f.filter((x) => dens(x, s.modes) >= s.tau).length, per = s.modes.map((_, i) => s.f.filter((x) => nearMode(x, s.modes) === i && dens(x, s.modes) >= s.tau).length), covered = s.round === 'case' ? per.filter((n) => n >= 1).length : per.filter((n) => n >= 3).length, need = s.round === 'play' ? 0 : s.modes.length, ok = pass >= s.need && covered >= need; return { label: s.round === 'case' ? 'Suggestions borrowed' : 'Forgeries that pass', text: `${pass} of ${s.f.length}` + (need ? `   ${s.round === 'case' ? 'subjects' : 'designs'} covered: ${covered} of ${need}` : ''), goal: `${s.need} or more` + (need ? ', all covered' : ''), frac: ok ? 1 : clamp((pass / s.f.length) * 0.6 + (need ? (covered / need) * 0.3 : 0.3), 0, 0.9), met: ok }; },
  demo(s) { const k = s.modes.length; s.f = s.f.map((_, i) => (s.round === 'case' ? (i < 9 ? s.modes[i % 3][0] : s.modes[3][0]) : s.modes[i % k][0]) + ((i % 5) - 2) * 0.004); },
};

// ---------- III-13 A map of covers ----------
const PAT = [(x, y) => y % 2 === 0, (x, y) => x % 2 === 0, (x, y) => (x + y) % 3 === 0, (x, y) => (x >> 1) % 2 === (y >> 1) % 2];
const mapped = new Map();
function coverMap(s) { if (!mapped.has(s.sig)) { if (mapped.size > 8) mapped.clear(); const r = new RNG(s.sig), X = R(24, (i) => R(64, (k) => { const on = PAT[i % 4](k % 8, k >> 3) ? 1 : 0; return r.chance(0.08) ? 1 - on : on; })), P = pca(X), v = P.vectors.slice(0, 2), codes = X.map((x) => v.map((q) => sum(q.map((c, j) => c * (x[j] - P.mu[j]))))); mapped.set(s.sig, { X, mu: P.mu, v, codes }); } return mapped.get(s.sig); }
const decode = (M, z) => M.mu.map((m, j) => clamp(m + z[0] * M.v[0][j] + z[1] * M.v[1][j], 0, 1));
export const III13 = {
  id: 'III-13', name: 'A map of covers', short: 'Latent spaces', formula: 'encode: each cover becomes two numbers, a place on the map\ndecode: any place on the map becomes a cover\nplaces between real covers decode to in-between covers',
  limit: 'A map is sharp where it has many examples. Where it has few, it draws something blurred and calls it a cover.',
  rounds: { play: { brief: 'Twenty-four invented book covers, squeezed to two numbers each: a map. Drag the probe. The decoder draws the cover for that place. Find the place that draws the cover in the frame.' }, twist: { brief: 'Walk between the groups. Find a place as far as you can get from every real cover, and see what the decoder draws there.' }, case: { brief: 'The Common Shelf’s map of books. Most sit in the middle. Drag the probe onto a rare book, a diamond, and count the neighbours it has.' } },
  hints: { play: ['Covers of one kind sit together.', 'Go to the group whose pattern matches, then look for the highlighted dot.'], twist: ['The middle of the map, between the groups.', 'Folio can go there.'], case: ['The diamonds are at the edges.', 'Drag onto any diamond.'] },
  teach: ['Squeeze every example down to a few numbers.', 'Treat those numbers as a place on a map.', 'Decode any place to get a new example, and be wary of empty regions.'],
  init(round, ctx) { const r = ctx.rng(round); if (round === 'case') { const pts = [...R(30, () => [r.n(0, 0.7), r.n(0, 0.7), 0]), ...R(4, (i) => [Math.cos(i * 1.7 + 0.5) * 3, Math.sin(i * 1.7 + 0.5) * 2.6, 1])]; return { round, pts, z: [0.2, 0.3] }; } const sig = r.int(1, 1e9), s = { round, sig, z: [0, 0], target: r.int(0, 23) }, M = coverMap(s); s.bd = bounds(M.codes, 0.8); s.z = [s.bd[0] + 0.5, s.bd[2] + 0.5]; return s; },
  far(s, z) { return Math.min(...coverMap(s).codes.map((c) => Math.hypot(c[0] - z[0], c[1] - z[1]))); },
  draw(b, s) {
    b.clear(); const A = area(b), u = A.u, g = b.g;
    if (s.round === 'case') { b.view(-4, 4, -3.4, 3.4, true); b.axes({ xt: 0, yt: 0, xfmt: () => '', yfmt: () => '', grid: false }); b.circle(s.z[0], s.z[1], 0.9, { color: WARM, fill: WARM, alpha: 0.12 }); s.pts.forEach((p) => b.dot(p[0], p[1], { color: DATA[p[2] ? 1 : 0], shape: p[2] ? 'diamond' : 'circle', r: p[2] ? 6 : 4 })); b.handle('z', s.z[0], s.z[1], { color: WARM, label: 'probe' }); return; }
    const M = coverMap(s), pic = (v, px, py, sz, cap) => { const c = sz / 8; v.forEach((q, k) => { const t = Math.round(255 - q * 210); g.fillStyle = `rgb(${t},${t + 3},${t + 10})`; g.fillRect(px + (k % 8) * c, py + (k >> 3) * c, c, c); }); b.box(px, py, sz, sz, { color: INK, width: 1.5 }); b.label(cap, px, py - 10 * u, { size: 11, bold: true }); };
    b.view(...s.bd, true); b.pad = { l: 30, r: 230, t: 18, b: 30 }; b.axes({ xt: 0, yt: 0, xfmt: () => '', yfmt: () => '', grid: false }); M.codes.forEach((c, i) => b.dot(c[0], c[1], { color: DATA[i % 4], shape: SHAPES[i % 4], r: s.round === 'play' && i === s.target ? 8 : 4.5, stroke: s.round === 'play' && i === s.target ? WARM : undefined })); b.handle('z', s.z[0], s.z[1], { color: WARM, label: 'probe' }); b.pad = { l: 46, r: 18, t: 18, b: 38 };
    const X = b.w - 200 * u; pic(decode(M, s.z), X, A.y + 30 * u, 150 * u, 'The decoder draws'); if (s.round === 'play') pic(M.X[s.target], X, A.y + 220 * u, 150 * u, 'Find this one');
  },
  drag(s, id, x, y) { if (id === 'z') s.z = s.round === 'case' ? [clamp(x, -3.8, 3.8), clamp(y, -3.2, 3.2)] : [clamp(x, s.bd[0], s.bd[1]), clamp(y, s.bd[2], s.bd[3])]; },
  meter(s) {
    if (s.round === 'case') { const nb = (z) => s.pts.filter((p) => Math.hypot(p[0] - z[0], p[1] - z[1]) < 0.9).length, on = s.pts.some((p) => p[2] && Math.hypot(p[0] - s.z[0], p[1] - s.z[1]) < 0.3); return { label: 'Books within reach of the probe', text: String(nb(s.z)), goal: 'put the probe on a rare book', frac: on ? 1 : 0.3, met: on, note: `in the middle of the map: ${nb([0, 0])} within reach` }; }
    const M = coverMap(s); if (s.round === 'play') { const d = Math.hypot(M.codes[s.target][0] - s.z[0], M.codes[s.target][1] - s.z[1]); return meterTo('Distance from the right place', d, 0.25, { lower: true, from: 6, fmt: (v) => v.toFixed(2) }); }
    let best = 0; for (let i = 0; i <= 30; i++) for (let j = 0; j <= 30; j++) { const z = [s.bd[0] + 0.8 + (i / 30) * (s.bd[1] - s.bd[0] - 1.6), s.bd[2] + 0.8 + (j / 30) * (s.bd[3] - s.bd[2] - 1.6)]; best = Math.max(best, III13.far(s, z)); } return meterTo('Distance to the nearest real cover', III13.far(s, s.z), best * 0.85, { from: 0, fmt: (v) => v.toFixed(2), note: 'No real cover looks like what is drawn here.' });
  },
  demo(s) { if (s.round === 'case') { const p = s.pts.find((q) => q[2]); s.z = [p[0], p[1]]; return; } const M = coverMap(s); if (s.round === 'play') { s.z = M.codes[s.target].slice(); return; } let best = [0, s.z]; for (let i = 0; i <= 30; i++) for (let j = 0; j <= 30; j++) { const z = [s.bd[0] + 0.8 + (i / 30) * (s.bd[1] - s.bd[0] - 1.6), s.bd[2] + 0.8 + (j / 30) * (s.bd[3] - s.bd[2] - 1.6)], d = III13.far(s, z); if (d > best[0]) best = [d, z]; } s.z = best[1]; },
};

// ---------- III-14 Out of the noise ----------
function dataOf(s) { if (s.round === 'play') return R(40, (i) => [Math.cos((i / 40) * 6.283) * 2, Math.sin((i / 40) * 6.283) * 2, 0, 1]); if (s.round === 'twist') return [...R(20, (i) => [-2 + ((i % 5) - 2) * 0.15, ((i >> 2) - 2) * 0.15, 0, 1]), ...R(20, (i) => [2 + ((i % 5) - 2) * 0.15, ((i >> 2) - 2) * 0.15, 1, 1])]; return [...R(18, (i) => [-2.2 + ((i % 5) - 2) * 0.15, 1 + ((i >> 2) - 2) * 0.15, 0, 1]), ...R(18, (i) => [2.2 + ((i % 5) - 2) * 0.15, 1 + ((i >> 2) - 2) * 0.15, 1, 1]), ...R(4, (i) => [((i % 2) - 0.5) * 0.3, -2 + ((i >> 1) - 0.5) * 0.3, 2, 1])]; }
function pull(p, D, sig) { let wx = 0, wy = 0, W = 0; for (const d of D) { const w = Math.exp(-((p[0] - d[0]) ** 2 + (p[1] - d[1]) ** 2) / (2 * sig * sig)); wx += w * d[0]; wy += w * d[1]; W += w; } if (W > 1e-12) return [wx / W, wy / W]; let b = D[0], bd = 1e9; for (const d of D) { const q = (p[0] - d[0]) ** 2 + (p[1] - d[1]) ** 2; if (q < bd) { bd = q; b = d; } } return [b[0], b[1]]; }
function backStep(s) { const D = dataOf(s), asked = s.round === 'twist' ? D.filter((d) => d[2] === 0) : s.round === 'case' ? D.filter((d) => d[2] !== 2) : D, sig = Math.max(0.25, 2.2 * Math.pow(0.9, s.t)), r = new RNG(s.seed + s.t), g = s.g || 0; s.p = s.p.map((p) => { const a = pull(p, D, sig), c = g ? pull(p, asked, sig) : a, tx = (a[0] + g * c[0]) / (1 + g), ty = (a[1] + g * c[1]) / (1 + g); return [p[0] + (tx - p[0]) * 0.22 + r.n(0, sig * 0.06), p[1] + (ty - p[1]) * 0.22 + r.n(0, sig * 0.06)]; }); s.t++; }
export const III14 = {
  id: 'III-14', name: 'Out of the noise', short: 'Diffusion', formula: 'forward: add a little noise, many times, until only noise is left\nbackward: learn to undo one small step\nguidance: push every step toward what was asked for',
  limit: 'Strong guidance gives the most typical result every time. What was unusual in the data stops coming out.',
  rounds: { play: { brief: 'The grey ring is the picture. The dots start as noise. Each step back, every dot is nudged along the arrows toward where real dots are. Step until they settle on the ring.' }, twist: { brief: 'Two groups. With no guidance the dots split between them. Raise guidance toward the left group and run again, until none land on the right.' }, case: { brief: 'Two large groups and one small, rare one. Raise guidance toward “typical” and run again, until the small group gets nothing.' } },
  hints: { play: ['Press “Ten steps back” a few times.', 'About thirty steps.'], twist: ['Drag guidance up, then “Start from noise” and step thirty times.', 'Guidance near 3.'], case: ['The same: raise guidance, start again, step.', 'Guidance near 2.'] },
  teach: ['Dissolve real examples into noise, step by step.', 'Train a network to undo one step.', 'Start from pure noise and walk back. Guidance steers the walk, and narrows it.'],
  init(round, ctx) { const seed = ctx.rng(round).int(1, 1e6), s = { round, seed, g: 0, t: 0 }; III14.noise(s); return s; },
  noise(s) { const r = new RNG(s.seed); s.p = R(40, () => [r.n(0, 2.3), r.n(0, 2.3)]); s.t = 0; },
  share(s, k) { const D = dataOf(s); return s.p.filter((p) => { let b = 0, bd = 1e9; D.forEach((d) => { const q = (p[0] - d[0]) ** 2 + (p[1] - d[1]) ** 2; if (q < bd) { bd = q; b = d[2]; } }); return b === k; }).length / s.p.length; },
  draw(b, s) { b.clear(); b.view(-4.2, 4.2, -3.4, 3.4, true); b.axes({ xt: 0, yt: 0, xfmt: () => '', yfmt: () => '', grid: false }); dataOf(s).forEach((d) => b.dot(d[0], d[1], { color: GREY, r: 3, stroke: null, alpha: 0.7 })); s.p.forEach((p) => b.dot(clamp(p[0], -4.1, 4.1), clamp(p[1], -3.3, 3.3), { color: DATA[1], r: 4.5 })); b.text('steps back: ' + s.t, 0, 3.2, { size: 11, color: INK2 }); },
  controls(s) { const c = [{ type: 'button', go: true, label: 'One step back', run: () => backStep(s) }, { type: 'button', label: 'Ten steps back', run: () => { for (let i = 0; i < 10; i++) backStep(s); } }, { type: 'button', label: 'Start from noise', run: () => III14.noise(s) }]; if (s.round !== 'play') c.unshift({ type: 'slider', label: s.round === 'twist' ? 'Guidance toward the left group' : 'Guidance toward “typical”', min: 0, max: 4, step: 0.1, value: s.g, set: (v) => { s.g = v; }, show: (v) => v.toFixed(1) }); return c; },
  meter(s) { if (s.round === 'play') { const D = dataOf(s), d = mean(s.p.map((p) => Math.min(...D.map((q) => Math.hypot(p[0] - q[0], p[1] - q[1]))))); return meterTo('Average distance from the ring', d, 0.3, { lower: true, from: 2.5, fmt: (v) => v.toFixed(2) }); } const k = s.round === 'twist' ? 1 : 2, sh = III14.share(s, k), ok = sh === 0 && s.t >= 25; return { label: s.round === 'twist' ? 'Dots that land in the right-hand group' : 'Dots that land in the rare group', text: pct(sh) + `   after ${s.t} steps`, goal: 'none, after 25 steps or more', frac: ok ? 1 : clamp(1 - sh * 2, 0, 0.9) * Math.min(1, s.t / 25), met: ok, note: `guidance ${s.g.toFixed(1)}` }; },
  demo(s) { if (s.round === 'play') { for (let i = 0; i < 40; i++) backStep(s); return; } for (const g of [2, 3, 4]) { s.g = g; III14.noise(s); for (let i = 0; i < 40; i++) backStep(s); if (III14.share(s, s.round === 'twist' ? 1 : 2) === 0) return; } },
};

// ---------- III-15 Make it look real ----------
