  controls(s) { if (s.round === 'case') return []; const c = [{ type: 'slider', label: 'Playouts', min: 5, max: 200, step: 5, value: s.n, set: (v) => { s.n = v; } }]; if (s.round === 'twist') c.push({ type: 'toggle', label: 'A hunch: prefer squares on your own open lines', value: s.hunch, set: (v) => { s.hunch = v; } }); return c; },
