  rounds: { play: { brief: 'A chain of beads. Tap a joint to bend everything after it by a quarter turn. Fold the chain so that each pair of same-coloured beads ends up side by side.' }, twist: { brief: 'No colours this time. The table lists beads that change together in related chains. Fold so those pairs touch.' }, case: { brief: 'Eight Common Shelf titles on a chain. Pairs borrowed by the same readers should sit together. Fold it. Two rare titles have no pairs at all.' } },
  hints: { play: ['Bend near one of a pair so its partner swings round.', 'Folio can fold it.'], twist: ['Read the pairs off the table.', 'Folio can fold it.'], case: ['Only the listed pairs matter.', 'Folio can fold it.'] },
  teach: ['A chain’s shape is decided by which parts end up touching.', 'Related chains tell you which parts those are.', 'With too few relatives, the shape is a guess.'],
