    if (s.round !== 'play') { b.label(s.round === 'case' ? 'Borrowed by the same readers' : 'Change together', A.x + 6 * u, A.y + 12 * u, { bold: true }); s.pairs.forEach(([i, j], k) => b.label(s.names ? `${i + 1}. ${s.names[i].slice(0, 22)}  +  ${j + 1}. ${s.names[j].slice(0, 22)}` : `beads ${i + 1} and ${j + 1}`, A.x + 6 * u, A.y + 32 * u + k * 18 * u, { size: 11 })); if (s.names) b.label(`no pairs known: ${[7, 8].map((i) => i + '. ' + s.names[i - 1].slice(0, 20)).join(',  ')}`, A.x + 6 * u, A.y + 32 * u + 2 * 18 * u, { size: 11, color: INK2 }); }
